// @generated by:gauntlet run:complete-inventory-adversarial
mod common;

use anatoly::{scan::scan_configured, scan_options::ScanOptions};
use common::{Server, limits, response};
use serde_json::{Value, json};

fn inspect(path: &str, body: &str) -> Value {
    inspect_status(path, body, "200 OK")
}

fn inspect_status(path: &str, body: &str, status: &str) -> Value {
    let body = body.to_owned();
    let status = status.to_owned();
    let server = Server::new(move |_| response(&status, "", &body));
    let mut options = ScanOptions {
        samples: 1,
        discover: false,
        ..ScanOptions::default()
    };
    options.network.no_proxy = true;
    let report = serde_json::to_value(
        scan_configured(&format!("{}{path}", server.url), limits(), &options).unwrap(),
    )
    .unwrap();
    assert_eq!(server.paths.lock().unwrap().len(), 1);
    report
}

fn find<'a>(report: &'a Value, name: &str) -> Option<&'a Value> {
    report["technologies"]
        .as_array()
        .unwrap()
        .iter()
        .find(|technology| technology["name"] == name)
}

#[test]
fn phpinfo_ignores_extension_rows_in_hidden_inert_and_documentation_containers() {
    for (open, close) in [
        ("<div hidden>", "</div>"),
        ("<div aria-hidden='true'>", "</div>"),
        ("<pre>", "</pre>"),
        ("<template>", "</template>"),
        ("<article>", "</article>"),
    ] {
        let report = inspect(
            "phpinfo.php",
            &format!(
                "<h1>PHP Version 8.4.26</h1><table>\
            <tr><td>Server API</td><td>FPM/FastCGI</td></tr>\
            <tr><td>PHP API</td><td>20240924</td></tr>\
            <tr><td>Redis Version</td><td>6.1.0</td></tr></table>\
            {open}<table><tr><td>OpenSSL Library Version</td><td>OpenSSL 9.9.9</td></tr></table>{close}"
            ),
        );
        assert_eq!(
            find(&report, "Redis").unwrap()["versions"],
            json!(["6.1.0"])
        );
        assert!(find(&report, "OpenSSL").is_none(), "{open}: {report}");
    }
}

#[test]
fn asset_query_suffixes_cannot_leak_through_normalized_version_hints() {
    for query in ["ver=1.2%2Bprivate-example", "ver=1.2-private-example"] {
        let report = inspect(
            "",
            &format!("<script src='/wp-content/plugins/calendar/main.js?{query}'></script>"),
        );
        let component = find(&report, "WordPress plugin:calendar").unwrap();
        assert!(
            !component["observations"]
                .as_array()
                .unwrap()
                .iter()
                .any(|observation| observation["method"] == "asset_version_hint")
        );
        assert_eq!(component["versions"], json!([]));
        assert!(!report.to_string().contains("private-example"));
    }
}

#[test]
fn legacy_npm_lockfiles_inventory_nested_production_dependencies_and_skip_dev_subtrees() {
    let report = inspect(
        "package-lock.json",
        r#"{
        "lockfileVersion":1,"dependencies":{
            "acme-parent":{"version":"1.2.3","dependencies":{
                "@acme/nested-widget":{"version":"2.0.1"}}},
            "acme-build-helper":{"version":"3.0.0","dev":true,"dependencies":{
                "acme-dev-child":{"version":"4.0.0"}}}
        }}"#,
    );
    for (name, version) in [
        ("npm:acme-parent", "1.2.3"),
        ("npm:@acme/nested-widget", "2.0.1"),
    ] {
        let package = find(&report, name).unwrap_or_else(|| panic!("missing {name}: {report}"));
        assert_eq!(package["versions"], json!([version]));
        assert_eq!(package["observations"][0]["method"], "npm_package");
        assert!(package["runtime_hint"].is_null());
    }
    for name in ["npm:acme-build-helper", "npm:acme-dev-child"] {
        assert!(find(&report, name).is_none());
    }
    assert_eq!(report["runtime"]["status"], "unknown");
}

#[test]
fn legacy_npm_dependency_depth_is_bounded() {
    let mut dependency = json!({"version":"1.0.0"});
    for depth in (0..12).rev() {
        dependency = json!({"version":"1.0.0", "dependencies":{
            format!("acme-depth-{depth}"):dependency
        }});
    }
    let report = inspect(
        "package-lock.json",
        &json!({
            "lockfileVersion":1,"dependencies":{"acme-root":dependency}
        })
        .to_string(),
    );
    assert!(find(&report, "npm:acme-root").is_some());
    assert!(find(&report, "npm:acme-depth-0").is_some());
    assert!(find(&report, "npm:acme-depth-11").is_none());
}

#[test]
fn plain_phpinfo_remains_parseable_when_unrelated_values_contain_angle_brackets() {
    let report = inspect(
        "phpinfo.php",
        "phpinfo()\nPHP Version => 8.4.26\n\
        Server API => FPM/FastCGI\nPHP API => 20240924\n\
        arbitrary value => <bracket\nRedis Version => 6.1.0\n",
    );
    assert_eq!(
        find(&report, "Redis").unwrap()["versions"],
        json!(["6.1.0"])
    );
}

#[test]
fn official_mongodb_and_zlib_fields_keep_compiled_and_linked_versions_separate() {
    for body in [
        "phpinfo()\nPHP Version => 8.4.26\nServer API => FPM/FastCGI\nPHP API => 20240924\n\
        mongodb\nMongoDB extension version => 2.1.0\nzlib\n\
        Compiled Version => 1.3.1\nLinked Version => 1.3.2\n\
        Unrelated Module\nCompiled Version => 9.9.9\n",
        "<h1>PHP Version 8.4.26</h1><table><tr><td>Server API</td><td>FPM/FastCGI</td></tr>\
        <tr><td>PHP API</td><td>20240924</td></tr></table>\
        <h2>mongodb</h2><table><tr><td>MongoDB extension version</td><td>2.1.0</td></tr></table>\
        <h2>zlib</h2><table><tr><td>Compiled Version</td><td>1.3.1</td></tr>\
        <tr><td>Linked Version</td><td>1.3.2</td></tr></table>\
        <h2>Unrelated Module</h2><table><tr><td>Compiled Version</td><td>9.9.9</td></tr></table>",
    ] {
        let report = inspect("phpinfo.php", body);
        assert_eq!(
            find(&report, "MongoDB").unwrap()["versions"],
            json!(["2.1.0"])
        );
        assert_eq!(
            find(&report, "zlib").unwrap()["versions"],
            json!(["1.3.1", "1.3.2"])
        );
        assert!(!report["technologies"].to_string().contains("9.9.9"));
    }
}

#[test]
fn standard_nginx_error_pages_reveal_server_versions_without_false_positive_article_matches() {
    let body = "<h1>404 Not Found</h1><hr><center>nginx/1.26.2</center>";
    let report = inspect_status("missing", body, "404 Not Found");
    assert_eq!(
        find(&report, "nginx").unwrap()["versions"],
        json!(["1.26.2"])
    );
    assert!(report["version"].is_null());
    assert!(report["version_candidates"].as_array().unwrap().is_empty());

    let successful = inspect("", body);
    assert!(find(&successful, "nginx").is_none());
    let article = inspect_status(
        "missing",
        &format!("<article>{body}</article>"),
        "404 Not Found",
    );
    assert!(find(&article, "nginx").is_none());
}
